// Re-export domain contracts generated by tauri-specta directly
export type {
  DailySheet,
  DDayEvent,
  DDayStatus,
  GamificationProfile,
  PlannerTask,
  Slot,
  StreakResult,
  SubjectItem,
  TimeBlock,
  TimerConfig,
  WeekDayStudy,
} from './bindings';

// Re-export branded primitives, types & adapters for consumers
export * from './branded';

import type { SubjectItem } from './bindings';
import type { EntityId, HexColor, UnixTimestampMs } from './branded';

// SubjectLegendItem = SubjectItem (bindings Specta).
// Branded types erosionados a propósito: el modelo viaja por IPC como string/string/number
// y los consumidores solo renderizan (color → CSS, id → key, slotIndex → índice de paleta).
// Si en el futuro se requiere validación estructural (slotIndex ∈ 0..7, color hex válido),
// aplicar el branded en el adapter de ENTRADA del binding, no en el tipo exportado.
export type SubjectLegendItem = SubjectItem;

export type TimerStatus = 'idle' | 'running' | 'paused';
export type TimerMode = 'stopwatch' | 'pomodoro';
export type PomodoroPhase = 'focus' | 'shortBreak' | 'longBreak';

export interface TimerState {
  status: TimerStatus;
  mode: TimerMode;
  startTimestamp: UnixTimestampMs | null;
  pausedTimestamp: UnixTimestampMs | null;
  accumulatedMs: number;
  currentSubjectId: EntityId | null;
  currentTaskId: EntityId | null;
  pomodoroPhase: PomodoroPhase;
  completedPomodorosInCycle: number;
}

